def equation(gate_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Equação empírica para log10(|ID|/A) ao longo da curva de transferência."""
    """Multiparameter equation compacta para log10(|ID|/A) em função de |VGS|."""
    a, b, c, d, e, f, g, h = parameters
    return a + b*gate_voltage_abs + c*np.exp(d*gate_voltage_abs) + e*np.exp(f*gate_voltage_abs) + g*np.exp(h*gate_voltage_abs)
